package com.djibtout.backend.entity;
import jakarta.persistence.*;
@Entity @Table(name="categories") public class Category { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String name; @Column(unique=true,nullable=false,length=140) private String slug; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="parent_id") private Category parent; private int displayOrder; private boolean active=true; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getSlug(){return slug;} public void setSlug(String v){slug=v;} public Category getParent(){return parent;} public void setParent(Category v){parent=v;} public int getDisplayOrder(){return displayOrder;} public void setDisplayOrder(int v){displayOrder=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
